<script setup lang="ts">
import{ref,watch}from'vue';import{useSalesScope}from'./use-sales-scope';import{qualificationStatusUrl,validQualificationStatus}from'./qualification-status';
const props=defineProps<{staff:any;doctorId:string;pending:any;busy:boolean}>(),emit=defineEmits(['clear','retry','unauthorized','access-lost']),status=ref<any>(null),checking=ref(false),checked=ref(false),error=ref(''),scope=useSalesScope(()=>JSON.stringify([props.staff.accountId,props.staff.employeeId,props.doctorId,props.pending]));
watch(()=>JSON.stringify([props.staff.accountId,props.staff.employeeId,props.doctorId,props.pending]),()=>{status.value=null;checking.value=false;checked.value=false;error.value='';},{flush:'sync'});
async function verify(){if(props.busy||checking.value||(props.pending?.phase&&props.pending.phase!=='pending'))return;const current=scope.begin('status');checking.value=true;error.value='';status.value=null;checked.value=false;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch(qualificationStatusUrl(props.pending,props.doctorId),{credentials:'same-origin',signal:controller.signal}),v=await r.json();if(!r.ok){if(current()&&r.status===401)emit('unauthorized');if(current()&&r.status===403)emit('access-lost');throw Error(v.message||'原提交核实失败。');}if(current())status.value=validQualificationStatus(props.pending,props.doctorId,v);}catch(e:any){if(current())error.value=e.message;}finally{clearTimeout(timer);if(current.active())checking.value=false;}}
function clear(){if(!props.busy&&!checking.value&&((props.pending?.phase&&props.pending.phase!=='pending')||status.value?.state==='completed'))emit('clear',props.pending);}
function retry(){if(!props.busy&&!checking.value&&checked.value&&status.value?.state==='not_found'&&!(props.pending?.phase&&props.pending.phase!=='pending')){validQualificationStatus(props.pending,props.doctorId,status.value);status.value=null;checked.value=false;emit('retry',props.pending);}}
</script>
<template><section class="b-alert warning"><template v-if="pending.phase&&pending.phase!=='pending'"><p>本机已记录原办理{{pending.phase==='rejected'?'被拒绝':'成功'}}，只需清理本机提示，不会重新保存。</p><button class="b-button outline" :disabled="busy" @click="clear">仅清理本机提示</button></template><template v-else><p>有一笔证书保存结果待核实，请先只读查询原请求。</p><button class="b-button outline" :disabled="busy||checking" @click="verify">{{checking?'正在核实…':'只读核实原提交'}}</button><p v-if="error" role="alert">{{error}}</p><template v-if="status?.state==='completed'"><p>已查到原结果 {{status.resultId}} · 第 {{status.version}} 版 · {{new Date(status.completedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}，这是原保存结果。</p><button class="b-button outline" :disabled="busy||checking" @click="clear">已核对，清理本机提示</button></template><template v-else-if="status?.state==='not_found'"><p>暂未见成功凭据，可能仍在处理、未提交或已回滚，不能据此认定未保存。</p><label><input type="checkbox" v-model="checked" :disabled="busy||checking"/>已核对，沿原请求号和原内容重试</label><button class="b-button outline" :disabled="busy||checking||!checked" @click="retry">重试原保存</button></template></template></section></template>
